/** Editor local: cópia temporária em disco; exportação sempre para um novo documento. */
public final class MainActivity extends Activity {
    private static final int PICK=1,SAVE=2,REPLACE=3,ADD=4;
    private static final long LIMIT=300L*1024*1024;
    private static final int MAX_TEXT=2*1024*1024, MAX_FILES=30000;
    private static final int BG=0xff0e0e10,PANEL=0xff202024,FG=0xfff3f3f5,DIM=0xffb2b2bb,RED=0xffd9263a;
    private final TreeMap<String,File> entries=new TreeMap<>();
    private File work; private String name="",mode="home",dir="",selected=""; private boolean archive=false,apk=false,dirty=false; private int serial=0;
    private LinearLayout root,body; private EditText editor; private String textValue="";
    private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.BLACK);getWindow().setNavigationBarColor(Color.BLACK);work=new File(getCacheDir(),"bravuz-work");removeTree(work);work.mkdirs();render();}
    private void removeTree(File f){if(f.isDirectory()){File[] a=f.listFiles();if(a!=null)for(File x:a)removeTree(x);}f.delete();}
    private GradientDrawable shape(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(10));return d;}
    private TextView label(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);return t;}
    private void para(String s){TextView t=label(s,14,DIM);t.setPadding(0,dp(8),0,dp(10));body.addView(t);}
    private void heading(String s){TextView t=label(s,23,FG);t.setTypeface(null,Typeface.BOLD);t.setPadding(0,dp(14),0,dp(6));body.addView(t);}
    private int iconColor(String title){if(title.contains("Selecionar"))return 0xff38bdf8;if(title.contains("instalado"))return 0xff9b87f5;if(title.contains("simples"))return 0xfff0ad41;if(title.contains("média"))return 0xff42c8a0;if(title.contains("profissional"))return 0xffb58bf5;if(title.contains("Análise"))return 0xff4dbfe1;if(title.contains("Salvar"))return 0xff58d8a3;if(title.contains("Imagem"))return 0xffffb45b;return 0xffe45b69;}
    /** Small vector icons drawn in code, avoiding emoji/font dependencies. */
    private final class ArtIcon extends android.view.View {
        final String kind; final Paint p=new Paint(3); final int color;
        ArtIcon(String k,int c){super(MainActivity.this);kind=k;color=c;}
        protected void onDraw(Canvas canvas){super.onDraw(canvas);float k=Math.min(getWidth(),getHeight())/40f;canvas.save();canvas.scale(k,k);p.setColor(color);p.setAlpha(45);canvas.drawRoundRect(0,0,40,40,11,11,p);p.setAlpha(255);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2.4f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);
            if(kind.contains("instalado")){canvas.drawRoundRect(10,8,30,32,4,4,p);canvas.drawLine(15,14,25,14,p);canvas.drawCircle(20,27,1,p);}
            else if(kind.contains("Análise")){canvas.drawCircle(18,18,8,p);canvas.drawLine(24,24,31,31,p);canvas.drawLine(14,19,17,22,p);canvas.drawLine(17,22,22,15,p);}
            else if(kind.contains("profissional")){canvas.drawLine(17,13,11,20,p);canvas.drawLine(11,20,17,27,p);canvas.drawLine(23,13,29,20,p);canvas.drawLine(29,20,23,27,p);canvas.drawLine(22,11,18,29,p);}
            else if(kind.contains("média")||kind.contains("Pasta")||kind.startsWith("DIR")){canvas.drawRoundRect(8,13,32,29,3,3,p);canvas.drawLine(9,13,9,10,p);canvas.drawLine(9,10,18,10,p);canvas.drawLine(18,10,21,13,p);}
            else if(kind.contains("Imagem")){canvas.drawRoundRect(8,9,32,31,3,3,p);canvas.drawCircle(16,16,2,p);canvas.drawLine(11,27,18,20,p);canvas.drawLine(18,20,23,25,p);canvas.drawLine(23,25,28,20,p);}
            else if(kind.contains("Salvar")){canvas.drawLine(20,9,20,24,p);canvas.drawLine(14,19,20,25,p);canvas.drawLine(20,25,26,19,p);canvas.drawLine(11,30,29,30,p);}
            else {canvas.drawRoundRect(11,8,29,32,3,3,p);canvas.drawLine(15,16,25,16,p);canvas.drawLine(15,21,25,21,p);canvas.drawLine(15,26,22,26,p);}p.setStyle(Paint.Style.FILL);canvas.restore();}
    }
    private void action(String title,String sub,boolean red,Runnable r){LinearLayout card=new LinearLayout(this);card.setOrientation(0);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(12),dp(12),dp(12),dp(12));card.setBackground(shape(red?RED:PANEL));LinearLayout.LayoutParams margin=new LinearLayout.LayoutParams(-1,-2);margin.setMargins(0,dp(7),0,0);body.addView(card,margin);ArtIcon icon=new ArtIcon(title,red?0xffffffff:iconColor(title));card.addView(icon,new LinearLayout.LayoutParams(dp(40),dp(40)));LinearLayout textColumn=new LinearLayout(this);textColumn.setPadding(dp(12),0,0,0);textColumn.setOrientation(1);card.addView(textColumn,new LinearLayout.LayoutParams(0,-2,1));TextView a=label(title,15,FG);a.setTypeface(null,Typeface.BOLD);textColumn.addView(a);if(!sub.isEmpty())textColumn.addView(label(sub,12,red?0xffffdfe2:DIM));TextView chevron=label("›",24,red?FG:DIM);card.addView(chevron);card.setOnClickListener(v->r.run());}
    private void alert(String title,String content){new AlertDialog.Builder(this).setTitle(title).setMessage(content).setPositiveButton("Entendi",null).show();}
    private void render(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(12),dp(18),dp(10));root.setBackgroundColor(BG);setContentView(root);
        LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);root.addView(bar);if(!mode.equals("home")){TextView back=label("‹",36,FG);back.setGravity(Gravity.CENTER);back.setContentDescription("Voltar à página anterior");back.setBackground(shape(PANEL));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(dp(42),dp(48));bp.setMargins(0,0,dp(10),0);bar.addView(back,bp);back.setOnClickListener(v->onBackPressed());}ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.brand);logo.setScaleType(ImageView.ScaleType.CENTER_CROP);bar.addView(logo,new LinearLayout.LayoutParams(dp(50),dp(50)));LinearLayout titles=new LinearLayout(this);titles.setOrientation(1);titles.setPadding(dp(12),0,0,0);bar.addView(titles);TextView title=label("BravuzEditor",21,FG);title.setTypeface(null,Typeface.BOLD);titles.addView(title);titles.addView(label("SA-MP • EDITOR DE ARQUIVOS",10,DIM));
        ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);
        switch(mode){case "home":home();break;case "menu":menu();break;case "simple":simple();break;case "medium":case "professional":browser();break;case "analysis":analysis();break;case "text":textScreen();break;case "images":images();break;}
        TextView support=label("✦  Clique aqui para acessar a comunidade  ›",14,FG);support.setTypeface(null,Typeface.BOLD);support.setGravity(Gravity.CENTER);support.setBackground(shape(0xff5865b8));support.setPadding(dp(8),dp(12),dp(8),dp(12));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,dp(8),0,0);root.addView(support,cp);support.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://discord.gg/SqqDTaBwYX")));}catch(Exception e){alert("Discord","Não foi possível abrir o navegador.");}});
    }
    private void home(){ImageView hero=new ImageView(this);hero.setImageResource(R.drawable.brand);hero.setScaleType(ImageView.ScaleType.FIT_CENTER);body.addView(hero,new LinearLayout.LayoutParams(-1,dp(200)));heading("Tudo começa aqui");para("Abra um arquivo ou explore uma cópia do APK base de um aplicativo instalado.");action("Selecionar arquivo","APK, ZIP, gamemode ou código • até 300 MiB",true,()->chooseFile());action("Aplicativo instalado","Escolher um app e abrir uma cópia do APK base",false,()->chooseInstalled());if(!entries.isEmpty())action("Continuar edição atual",name+(dirty?" • alterações não exportadas":""),false,()->go("menu"));para("Pastas precisam ser compactadas em ZIP. Alguns apps instalados usam vários APKs ou bloqueiam acesso.");}
    private void chooseFile(){if(entries.isEmpty()||!dirty){pick(PICK);return;}new AlertDialog.Builder(this).setTitle("Abrir outro arquivo?").setMessage("As alterações da cópia atual serão perdidas se você escolher outro arquivo. Para mantê-las, volte e exporte uma cópia.").setNegativeButton("Cancelar",null).setPositiveButton("Selecionar",(d,w)->pick(PICK)).show();}
    private void chooseInstalled(){if(entries.isEmpty()||!dirty){installedApps();return;}new AlertDialog.Builder(this).setTitle("Abrir outro aplicativo?").setMessage("As alterações da cópia atual serão perdidas ao abrir outro app. Exporte antes se quiser guardá-las.").setNegativeButton("Cancelar",null).setPositiveButton("Continuar",(d,w)->installedApps()).show();}
    private void installedApps(){
        PackageManager pm=getPackageManager();ArrayList<ApplicationInfo> apps=new ArrayList<>();try{for(ApplicationInfo a:pm.getInstalledApplications(0))if(a.sourceDir!=null && pm.getLaunchIntentForPackage(a.packageName)!=null)apps.add(a);}catch(Exception e){alert("Aplicativos instalados","Não foi possível obter a lista: "+e.getMessage());return;}
        Collections.sort(apps,(a,b)->String.CASE_INSENSITIVE_ORDER.compare(pm.getApplicationLabel(a).toString(),pm.getApplicationLabel(b).toString()));
        if(apps.isEmpty()){alert("Nenhum app visível","O Android não retornou aplicativos disponíveis. Você ainda pode selecionar um arquivo APK.");return;}
        LinearLayout box=new LinearLayout(this);box.setPadding(dp(16),0,dp(16),0);box.setOrientation(1);EditText search=new EditText(this);search.setSingleLine(true);search.setHint("Buscar aplicativo");box.addView(search);ListView list=new ListView(this);box.addView(list,new LinearLayout.LayoutParams(-1,dp(360)));ArrayList<ApplicationInfo> shown=new ArrayList<>();ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,new ArrayList<String>());list.setAdapter(adapter);
        Runnable update=()->{String q=search.getText().toString().toLowerCase(Locale.ROOT);shown.clear();adapter.clear();for(ApplicationInfo a:apps){String label=pm.getApplicationLabel(a).toString();if(label.toLowerCase(Locale.ROOT).contains(q)||a.packageName.toLowerCase(Locale.ROOT).contains(q)){shown.add(a);adapter.add(label+"\n"+a.packageName);}}adapter.notifyDataSetChanged();};
        search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){update.run();}public void afterTextChanged(android.text.Editable e){}});update.run();AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Aplicativos instalados").setView(box).setNegativeButton("Cancelar",null).create();list.setOnItemClickListener((parent,view,pos,id)->{ApplicationInfo a=shown.get(pos);String label=pm.getApplicationLabel(a).toString();boolean split=a.splitSourceDirs!=null&&a.splitSourceDirs.length>0;dialog.dismiss();new AlertDialog.Builder(this).setTitle(label).setMessage("O editor abrirá apenas uma cópia do APK base. O aplicativo instalado não será alterado diretamente."+(split?"\n\nEste app possui APKs adicionais (split); eles não serão incluídos nesta versão.":"")+"\n\nA exportação será sem assinatura e não estará pronta para instalar.").setNegativeButton("Cancelar",null).setPositiveButton("Abrir cópia",(d,w)->load(Uri.fromFile(new File(a.sourceDir)),label+".apk")).show();});dialog.show();
    }
    private void menu(){heading("Escolha como trabalhar");para(name+(dirty?" • contém alterações":""));action("Edição simples","Renomear a cópia; acessar imagens",true,()->go("simple"));action("Edição média","Navegar por pastas e editar arquivos",false,()->{dir="";go("medium");});action("Edição profissional","Lista completa de caminhos e detalhes",false,()->{dir="";go("professional");});action("Análises","Resumo e avisos básicos sobre o arquivo",false,()->go("analysis"));action("Selecionar outro arquivo","Descartar a cópia de trabalho atual",false,()->confirmClose());}
    private void simple(){heading("Edição simples");para("Arquivo selecionado: "+name);action("Nome da cópia exportada",name,false,()->renameExport());if(archive){action("Imagens do arquivo","Visualizar ou substituir imagens encontradas",false,()->go("images"));para("O nome visível e o ícone instalados de um APK usam recursos compilados. Esta versão ainda não altera esses campos automaticamente.");}else{action("Editar arquivo de texto","Disponível apenas para conteúdo UTF-8",false,()->openEditor(""));}action("Salvar cópia","Escolher onde salvar",true,()->savePrompt());action("‹ Voltar ao menu","",false,()->go("menu"));}
    private void renameExport(){EditText field=new EditText(this);field.setSingleLine(true);field.setText(name);new AlertDialog.Builder(this).setTitle("Nome da cópia").setView(field).setNegativeButton("Cancelar",null).setPositiveButton("Confirmar",(d,w)->{String n=field.getText().toString().trim();if(!validName(n)){alert("Nome inválido","Use um nome simples, sem barras.");return;}name=n;render();}).show();}
    private void images(){heading("Imagens");para("Toque para visualizar ou substituir. A troca de imagem não garante alterar o ícone do aplicativo.");int count=0;for(String n:entries.keySet()){String s=n.toLowerCase(Locale.ROOT);if(s.endsWith(".png")||s.endsWith(".jpg")||s.endsWith(".jpeg")||s.endsWith(".webp")){final String key=n;action(key,format(entries.get(key).length()),false,()->fileMenu(key));if(++count>=500){para("Lista limitada às primeiras 500 imagens.");break;}}}if(count==0)para("Nenhuma imagem reconhecida.");action("‹ Voltar","",false,()->go("simple"));}
    private void browser(){heading(mode.equals("professional")?"Edição profissional":"Edição média");if(!archive){para("Este arquivo não é um APK ou ZIP reconhecido. Você pode editá-lo se for texto UTF-8.");action("Abrir como texto","",true,()->openEditor(""));action("Salvar cópia","",false,()->savePrompt());action("‹ Menu","",false,()->go("menu"));return;}
        para(mode.equals("professional")?"Caminhos completos • "+entries.size()+" arquivos":"Pasta: /"+dir);
        action("Salvar cópia",apk?"APK exportado sem assinatura":"Arquivo ZIP",true,()->savePrompt());
        if(mode.equals("medium")){action("Adicionar arquivo nesta pasta","",false,()->pick(ADD));if(!dir.isEmpty())action("‹ Pasta anterior","",false,()->{String d=dir.substring(0,dir.length()-1);int i=d.lastIndexOf('/');dir=i<0?"":d.substring(0,i+1);render();});TreeSet<String> folders=new TreeSet<>();ArrayList<String> paths=new ArrayList<>();for(String path:entries.keySet()){if(!path.startsWith(dir))continue;String rest=path.substring(dir.length());int slash=rest.indexOf('/');if(slash>=0)folders.add(rest.substring(0,slash));else paths.add(path);}for(String f:folders)action("DIR  "+f,"Pasta",false,()->{dir+=f+"/";render();});int i=0;for(String p:paths){if(++i>1000){para("Exibindo até 1.000 arquivos nesta pasta.");break;}action("ARQ  "+p.substring(dir.length()),format(entries.get(p).length()),false,()->fileMenu(p));}}
        else{int i=0;for(String p:entries.keySet()){if(++i>1000){para("Exibindo até 1.000 caminhos. Use a edição média para navegar pelas demais pastas.");break;}action(p,format(entries.get(p).length()),false,()->fileMenu(p));}}
        action("‹ Voltar ao menu","",false,()->go("menu"));}
    private void fileMenu(String path){selected=path;new AlertDialog.Builder(this).setTitle(path).setItems(new String[]{"Visualizar", "Editar texto UTF-8", "Substituir", "Renomear", "Excluir"},(dialog,which)->{switch(which){case 0:preview(path);break;case 1:openEditor(path);break;case 2:pick(REPLACE);break;case 3:renameEntry(path);break;case 4:new AlertDialog.Builder(this).setTitle("Excluir arquivo?").setMessage(path).setNegativeButton("Cancelar",null).setPositiveButton("Excluir",(d,w)->{File f=entries.remove(path);if(f!=null)f.delete();dirty=true;render();}).show();break;}}).show();}
    private void preview(String path){File f=entries.get(path);String n=path.toLowerCase(Locale.ROOT);if(n.endsWith(".png")||n.endsWith(".jpg")||n.endsWith(".jpeg")||n.endsWith(".webp")){android.graphics.BitmapFactory.Options o=new android.graphics.BitmapFactory.Options();o.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeFile(f.getPath(),o);o.inJustDecodeBounds=false;o.inSampleSize=1;while(o.outWidth/o.inSampleSize>1200||o.outHeight/o.inSampleSize>1200)o.inSampleSize*=2;android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeFile(f.getPath(),o);if(bitmap!=null){ImageView iv=new ImageView(this);iv.setImageBitmap(bitmap);iv.setAdjustViewBounds(true);new AlertDialog.Builder(this).setTitle(path).setView(iv).setPositiveButton("Fechar",null).show();return;}}openEditor(path);}
    private void renameEntry(String key){EditText field=new EditText(this);String prefix=key.contains("/")?key.substring(0,key.lastIndexOf('/')+1):"";field.setSingleLine(true);field.setText(key.substring(prefix.length()));new AlertDialog.Builder(this).setTitle("Renomear arquivo").setView(field).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",(d,w)->{String n=field.getText().toString().trim(),dest=prefix+n;if(!validName(n)||entries.containsKey(dest)){alert("Nome inválido","Escolha um nome que ainda não exista nesta pasta.");return;}entries.put(dest,entries.remove(key));dirty=true;render();}).show();}
    private void openEditor(String path){File f=entries.get(path);try{if(f.length()>MAX_TEXT)throw new IOException("O editor de texto aceita até 2 MiB.");byte[] data=readSmall(f);StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(data));for(byte b:data)if(b==0)throw new IOException("Arquivo binário não pode ser editado como texto.");textValue=new String(data,StandardCharsets.UTF_8);selected=path;go("text");}catch(Exception ex){alert("Não foi possível abrir como texto",ex.getMessage()==null?"Não é texto UTF-8 válido.":ex.getMessage());}}
    private String textReturn="menu"; private void go(String next){if(next.equals("text"))textReturn=mode;mode=next;render();}
    private void textScreen(){heading("Editor de texto");para(selected.isEmpty()?name:selected);editor=new EditText(this);editor.setText(textValue);editor.setTextColor(FG);editor.setBackground(shape(PANEL));editor.setPadding(dp(12),dp(12),dp(12),dp(12));editor.setGravity(Gravity.TOP);editor.setTypeface(Typeface.MONOSPACE);editor.setTextSize(14);body.addView(editor,new LinearLayout.LayoutParams(-1,dp(350)));action("Aplicar alteração","Altera somente a cópia de trabalho",true,()->{byte[] b=editor.getText().toString().getBytes(StandardCharsets.UTF_8);if(b.length>MAX_TEXT){alert("Texto muito grande","Limite de 2 MiB.");return;}try{File target=entries.get(selected);try(FileOutputStream out=new FileOutputStream(target)){out.write(b);}dirty=true;mode=textReturn;render();}catch(IOException e){alert("Erro ao salvar",e.toString());}});action("Descartar e voltar","",false,()->{mode=textReturn;render();});}
    private void analysis(){heading("Análises");long total=0;int pics=0,dex=0,libs=0,source=0;for(Map.Entry<String,File> e:entries.entrySet()){total+=e.getValue().length();String s=(e.getKey().isEmpty()?name:e.getKey()).toLowerCase(Locale.ROOT);if(s.endsWith(".png")||s.endsWith(".jpg")||s.endsWith(".webp"))pics++;if(s.endsWith(".dex"))dex++;if(s.endsWith(".so"))libs++;if(s.endsWith(".pwn")||s.endsWith(".inc"))source++;}para("Nome: "+name+"\nTipo detectado: "+(apk?"APK":archive?"ZIP":"Arquivo individual")+"\nArquivos: "+entries.size()+"\nTamanho de trabalho: "+format(total)+"\nImagens: "+pics+" • DEX: "+dex+" • Bibliotecas: "+libs+"\nFontes Pawn: "+source);if(apk)para("Aviso: editar e exportar remove assinaturas antigas. O arquivo resultante precisa ser reconstruído quando necessário, alinhado e assinado antes de instalar.");if(archive&&!entries.containsKey("AndroidManifest.xml"))para("Nenhum AndroidManifest.xml encontrado na raiz.");para("Verificações limitadas: leitura de ZIP e contagens. Não compila Pawn, não detecta todos os erros, não testa segurança, assinatura, compatibilidade ou funcionamento.");action("‹ Voltar ao menu","",false,()->go("menu"));}
    private String format(long n){return n<1024?n+" B":n<1024*1024?String.format(Locale.US,"%.1f KiB",n/1024.0):String.format(Locale.US,"%.1f MiB",n/1048576.0);}
    private void pick(int req){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");try{startActivityForResult(i,req);}catch(Exception e){alert("Seletor indisponível",e.toString());}}
    private void savePrompt(){if(apk){new AlertDialog.Builder(this).setTitle("APK sem assinatura").setMessage("A cópia exportada não estará pronta para instalar. Ela precisará ser alinhada e assinada; mudanças em recursos compilados podem exigir reconstrução.").setNegativeButton("Cancelar",null).setPositiveButton("Continuar",(d,w)->savePicker()).show();}else savePicker();}
    private void savePicker(){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,name);try{startActivityForResult(i,SAVE);}catch(Exception e){alert("Não foi possível salvar",e.toString());}}
    private void confirmClose(){new AlertDialog.Builder(this).setTitle("Trocar arquivo?").setMessage("Alterações não exportadas serão perdidas.").setNegativeButton("Cancelar",null).setPositiveButton("Continuar",(d,w)->pick(PICK)).show();}
    private String getName(Uri u){try(Cursor c=getContentResolver().query(u,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst()&&!c.isNull(0))return c.getString(0);}catch(Exception ignored){}return "arquivo";}
    private boolean validName(String s){return !s.isEmpty()&&!s.equals(".")&&!s.equals("..")&&!s.contains("/")&&!s.contains("\\")&&!s.contains("\u0000");}
    private boolean safe(String s){if(s.isEmpty()||s.startsWith("/")||s.contains("\\")||s.contains("\u0000"))return false;for(String p:s.split("/"))if(p.equals("..")||p.equals("."))return false;return true;}
    private long copy(InputStream in,OutputStream out,long cap)throws IOException{byte[] buf=new byte[32768];long n=0;int k;while((k=in.read(buf))!=-1){n+=k;if(n>cap)throw new IOException("Limite de 300 MiB excedido.");out.write(buf,0,k);}return n;}
    private byte[] readSmall(File f)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(f)){copy(in,out,MAX_TEXT);}return out.toByteArray();}
    private File newFile(){return new File(work,"part-"+(serial++));}
    private boolean signature(String s){String n=s.toUpperCase(Locale.ROOT);if(!n.startsWith("META-INF/"))return false;n=n.substring(9);return !n.contains("/")&&(n.equals("MANIFEST.MF")||n.endsWith(".SF")||n.endsWith(".RSA")||n.endsWith(".DSA")||n.endsWith(".EC")||n.startsWith("SIG-"));}
    interface Task{void run()throws Exception;}
    private void task(String msg,Task t,Runnable done){android.app.ProgressDialog p=new android.app.ProgressDialog(this);p.setMessage(msg);p.setCancelable(false);p.show();new Thread(()->{try{t.run();runOnUiThread(()->{p.dismiss();if(done!=null)done.run();render();});}catch(Exception ex){runOnUiThread(()->{p.dismiss();alert("Não foi possível concluir",ex.getMessage()==null?ex.toString():ex.getMessage());});}}).start();}
    private void load(Uri uri){load(uri,getName(uri));}
    private void load(Uri uri,String fileName){task("Abrindo arquivo...",()->{File incoming=newFile();TreeMap<String,File> temp=new TreeMap<>();boolean isArchive=false,isApk=false;try{try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(incoming)){copy(in,out,LIMIT);}try(InputStream in=new FileInputStream(incoming)){int a=in.read(),b=in.read();isArchive=a==0x50&&b==0x4b;}if(isArchive){long total=0;int count=0;try(ZipInputStream zip=new ZipInputStream(new FileInputStream(incoming))){ZipEntry e;while((e=zip.getNextEntry())!=null){if(++count>MAX_FILES)throw new IOException("O arquivo contém mais de 30.000 entradas.");String path=e.getName();if(!safe(path))throw new IOException("Caminho inseguro no arquivo compactado.");if(!e.isDirectory()){if(temp.containsKey(path))throw new IOException("Caminhos duplicados no arquivo compactado.");File part=newFile();temp.put(path,part);try(OutputStream out=new FileOutputStream(part)){total+=copy(zip,out,LIMIT-total);} }zip.closeEntry();}}if(count==0)throw new IOException("ZIP vazio ou inválido.");isApk=temp.containsKey("AndroidManifest.xml");incoming.delete();}else temp.put("",incoming);
        for(File old:entries.values())old.delete();entries.clear();entries.putAll(temp);archive=isArchive;apk=isApk;name=fileName;dir="";dirty=false;mode="menu";
        }catch(Exception e){incoming.delete();for(File f:temp.values())f.delete();throw e;}},null);}
    private void replace(Uri uri,boolean add){String path=add?dir+getName(uri):selected;if(add&&(!validName(getName(uri))||entries.containsKey(path))){alert("Arquivo não adicionado","Nome inválido ou arquivo já existente.");return;}task("Copiando arquivo...",()->{File temp=newFile();try{long total=0;for(Map.Entry<String,File> e:entries.entrySet())if(!e.getKey().equals(path))total+=e.getValue().length();try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(temp)){copy(in,out,LIMIT-total);}File old=entries.put(path,temp);if(old!=null)old.delete();dirty=true;}catch(Exception e){temp.delete();throw e;}},null);}
    private void save(Uri uri){task("Salvando cópia...",()->{try(OutputStream raw=getContentResolver().openOutputStream(uri,"wt")){if(raw==null)throw new IOException("Destino indisponível.");if(archive){try(ZipOutputStream z=new ZipOutputStream(raw)){for(Map.Entry<String,File> e:entries.entrySet()){if(apk&&signature(e.getKey()))continue;z.putNextEntry(new ZipEntry(e.getKey()));try(InputStream in=new FileInputStream(e.getValue())){copy(in,z,LIMIT);}z.closeEntry();}}}else{try(InputStream in=new FileInputStream(entries.get(""))){copy(in,raw,LIMIT);}}}},()->alert("Cópia salva",apk?"Arquivo exportado sem assinatura. Ainda não está pronto para instalação.":"Arquivo salvo no local escolhido."));}
    @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(res!=RESULT_OK||data==null||data.getData()==null)return;Uri u=data.getData();if(req==PICK)load(u);else if(req==REPLACE)replace(u,false);else if(req==ADD)replace(u,true);else if(req==SAVE)save(u);}
    @Override public void onBackPressed(){if(mode.equals("home")){super.onBackPressed();return;}if(mode.equals("text")){new AlertDialog.Builder(this).setTitle("Descartar edição?").setNegativeButton("Continuar",null).setPositiveButton("Descartar",(d,w)->{mode=textReturn;render();}).show();return;}if(mode.equals("menu")){go("home");return;}if(mode.equals("images")){go("simple");return;}if(mode.equals("medium")&&!dir.isEmpty()){String d=dir.substring(0,dir.length()-1);int i=d.lastIndexOf('/');dir=i<0?"":d.substring(0,i+1);render();return;}go("menu");}
}
